CREATE FUNCTION audit.organization_before_write() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP = 'DELETE' THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='ARCHIVE_REQUIRED'; END IF;
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.reference IS DISTINCT FROM OLD.reference OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.created_by IS DISTINCT FROM OLD.created_by OR (to_jsonb(NEW)->'business_id') IS DISTINCT FROM (to_jsonb(OLD)->'business_id') THEN RAISE EXCEPTION 'IMMUTABLE_IDENTITY'; END IF;
 NEW.version := OLD.version + 1;
 NEW.updated_at := clock_timestamp();
 NEW.updated_by := current_user;
 RETURN NEW;
END $$

CREATE FUNCTION audit.organization_after_write() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 INSERT INTO audit.organization_history(object_type,object_id,version,snapshot) VALUES(TG_TABLE_NAME,NEW.id,NEW.version,to_jsonb(NEW));
 RETURN NEW;
END $$
